{"query":"query FortisSuiTransfers {
        address(address: "0xa1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1a1") {
          transactions(last: 50, relation: AFFECTED) {
            pageInfo { hasPreviousPage startCursor }
            nodes {
              digest
              sender { address }
              gasInput { gasSponsor { address } }
              kind { __typename }
              effects {
                status
                executionError { message }
                timestamp
                checkpoint { sequenceNumber }
                balanceChangesJson
                objectChanges(first: 100) {
                  pageInfo { hasNextPage endCursor }
                  nodes {
                    address
                    idCreated
                    inputState {
                      owner {
                        ... on AddressOwner { address { address } }
                      }
                    }
                    outputState {
                      owner {
                        ... on AddressOwner { address { address } }
                      }
                      asMoveObject {
                        contents {
                          type { repr }
                          display { output }
                        }
                      }
                    }
                  }
                }
                gasEffects {
                  gasSummary { computationCost storageCost storageRebate }
                }
              }
            }
          }
        }
      }"}

